const n = (count: string, one: string, many: string) => `${count} ${count === '1' ? one : many}`;

/** Phrases with a number or a name in them. */
export const ES_PATTERNS: Language['patterns'] = [
  [/^(.+): (\d+) remark\(s\) added, (\d+) updated\.$/, (m) => `${m[1]}: ${m[2]} observación(es) añadida(s), ${m[3]} actualizada(s).`],
  [/^Importing (.+)$/, (m) => `Importando ${m[1]}`],
  [/^Linking (.+)$/, (m) => `Vinculando ${m[1]}`],
  [/^Reading (.+\.ifc)$/i, (m) => `Leyendo ${m[1]}`],
  [/^(.+) — ([^·]+?)(?: · (.+))?$/, (m) => `${ES[m[1]] ?? m[1]} — ${m[2]}${m[3] ? ` · ${ES[m[3]] ?? m[3]}` : ''}`],
  [/^(Fold|Unfold) the (project browser|properties)(?: \((.+)\))?$/, (m) => `${m[1] === 'Fold' ? 'Plegar' : 'Desplegar'} ${m[2] === 'properties' ? 'las propiedades' : 'el navegador de proyectos'}${m[3] ? ` (${m[3]})` : ''}`],
  [/^Keep the (project browser|properties) open(?: \((.+)\))?$/, (m) => `Mantener ${m[1] === 'properties' ? 'abiertas las propiedades' : 'abierto el navegador de proyectos'}${m[2] ? ` (${m[2]})` : ''}`],
  [/^Quick tool (\d)$/, (m) => `Herramienta rápida ${m[1]}`],
  [/^Object snap \((.+)\)$/, (m) => `Referencia a objetos (${m[1]})`],
  [/^Ortho \((.+); hold Shift\)$/, (m) => `Orto (${m[1]}; mantener Mayús)`],
  [/^Polar tracking every 45° \((.+)\)$/, (m) => `Rastreo polar cada 45° (${m[1]})`],
  [/^Reassign to (.+)$/, (m) => `Reasignar a ${ES[m[1]] ?? m[1]}`],
  [/^Also used by (.+)$/, (m) => `También lo usa ${m[1]}`],
  [/^In (.+)'s session, to look$/, (m) => `En la sesión de ${m[1]}, como observador`],
  [/^In (.+)'s session$/, (m) => `En la sesión de ${m[1]}`],
  [/^(.+) is in this plan\.$/, (m) => `${m[1]} está en esta planta.`],
  [/^(.+) is in 3D\.$/, (m) => `${m[1]} está en 3D.`],
  [/^Undo „(.+)”: (.+) changed it after you; it is left as it is\.$/, (m) => `Deshacer „${m[1]}”: ${m[2] === 'Someone' ? 'otra persona' : m[2]} lo cambió después de usted; se deja como está.`],
  [/^Redo „(.+)”: (.+) changed it after you; it is left as it is\.$/, (m) => `Rehacer „${m[1]}”: ${m[2] === 'Someone' ? 'otra persona' : m[2]} lo cambió después de usted; se deja como está.`],
  [/^Segment (\d+) \((m|°|ratio)\)$/, (m) => `Segmento ${m[1]} (${m[2] === 'ratio' ? 'proporción' : m[2]})`],
  [/^(aligned|linear) · (\d+) segments$/, (m) => `${m[1] === 'aligned' ? 'alineada' : 'lineal'} · ${m[2]} segmentos`],
  [/^(\d+) elements?$/, (m) => n(m[1], 'elemento', 'elementos')],
  [/^(\d+) of (\d+) storeys$/, (m) => `${m[1]} de ${m[2]} plantas`],
  [/^cut at (.+) m$/, (m) => `cortado a ${m[1]} m`],
  [/^Underlay: (.+)$/, (m) => `Calco: ${m[1]}`],
  [/^(\d+) (survey points|feature\(s\)|building\(s\)) imported, in the project's coordinates \(Manage → Location shows its system and survey point\)\.$/, (m) => `${m[1]} ${({ 'survey points': 'puntos topográficos', 'feature(s)': 'elemento(s)', 'building(s)': 'edificio(s)' } as Record<string, string>)[m[2]]} importados, en las coordenadas del proyecto (Gestionar → Ubicación muestra su sistema y su punto de reconocimiento).`],
  [/^(\d+) to check$/, (m) => `${m[1]} por revisar`],
  [/^Plan · (.+)$/, (m) => `Planta · ${m[1]}`],
  [/^(\d+) line edit\(s\) lost their edge · clean$/, (m) => `${m[1]} edición(es) de línea perdieron su arista · limpiar`],
  [/^view range: (\d+) problem\(s\)$/, (m) => `rango de vista: ${m[1]} problema(s)`],
  [/^(.+) · (\d+) selected$/, (m) => `${m[1]} · ${m[2]} seleccionados`],
  [/^Camera at (.+) m: drag$/, (m) => `Cámara a ${m[1]} m: arrastre`],
  [/^(Key plan|On screen|Seen from|Cut at) · (.+)$/, (m) => `${({ 'Key plan': 'Plano clave', 'On screen': 'En pantalla', 'Seen from': 'Visto desde', 'Cut at': 'Cortado en' } as Record<string, string>)[m[1]]} · ${m[2]}`],
  [/^Terrain created from (\d+) points\.$/, (m) => `Terreno creado a partir de ${m[1]} puntos.`],
  [/^(\d+) element\(s\) moved to (.+)\.$/, (m) => `${m[1]} elemento(s) movido(s) a ${m[2]}.`],
  [/^(\d+) element\(s\) selected, now on (.+)\.$/, (m) => `${m[1]} elemento(s) seleccionado(s), ahora en ${m[2]}.`],
  [/^Type parameters · (.+)$/, (m) => `Parámetros de tipo · ${m[1]}`],
  [/^(\d+) bays along × (\d+) up · IFC: (.+)$/, (m) => `${m[1]} módulos a lo largo × ${m[2]} hacia arriba · IFC: ${m[3]}`],
  [/^(\d+) value\(s\) added\.$/, (m) => `${m[1]} valor(es) añadido(s).`],
  [/^(\d+) room\(s\) updated\.$/, (m) => `${m[1]} habitación(es) actualizada(s).`],
  [/^IFC properties · (\d+)$/, (m) => `Propiedades IFC · ${m[1]}`],
  [/^(.+) could not be read as a picture: attach a PNG or JPEG screenshot \(or send the report without one\)\.$/, (m) => `${m[1]} no se pudo leer como imagen: adjunte una captura PNG o JPEG (o envíe el informe sin ella).`],
  [/^(\d+) room\(s\) updated; (\d+) no longer enclosed \(they keep their last outline\)\.$/, (m) => `${m[1]} habitación(es) actualizada(s); ${m[2]} ya no cerrada(s) (conservan su último contorno).`],
  [/^No room has a value for this field yet\. Give rooms a (.+) in their properties\.$/, (m) => `Ninguna habitación tiene aún un valor para este campo. Asigne a las habitaciones un valor (${m[1]}) en sus propiedades.`],
  // The model assistant's lines: its steps, its tables, what it applied
  [/^Listed (\d+) of (\d+) · (.+)$/, (m) => `Listó ${m[1]} de ${m[2]} · ${m[3] === 'all' ? 'todos' : m[3]}`],
  [/^Computed (\d+) group\(s\) over (\d+) element\(s\)$/, (m) => `Calculó ${m[1]} grupo(s) sobre ${m[2]} elemento(s)`],
  [/^Read element (.+)$/, (m) => `Leyó el elemento ${m[1]}`],
  [/^Read schedule (.+)$/, (m) => `Leyó la tabla ${m[1]}`],
  [/^Proposed (\d+) change\(s\)$/, (m) => `Propuso ${m[1]} cambio(s)`],
  [/^Proposed (\d+) change\(s\), (\d+) refused$/, (m) => `Propuso ${m[1]} cambio(s), ${m[2]} rechazado(s)`],
  [/^Tool failed: (.+)$/, (m) => `La herramienta falló: ${m[1]}`],
  [/^(\d+) row\(s\)$/, (m) => `${m[1]} fila(s)`],
  [/^(\d+) value\(s\) applied: one step to undo\.$/, (m) => `${m[1]} valor(es) aplicado(s): un solo paso para deshacer.`],
  [/^Grouped by (.+)$/, (m) => `Agrupado por ${m[1]}`],
  [/^(\d+) of (\d+) ticked$/, (m) => `${m[1]} de ${m[2]} marcados`],
  // The report form
  [/^The app's version and its last (\d+) error message\(s\) go with the report\.$/, (m) => `La versión de la aplicación y sus últimos ${m[1]} mensajes de error acompañan al informe.`],
  [/^Thank you: report #(\d+) is on its way\.( Replies will appear in Help → Messages\.)?$/, (m) => `Gracias: el informe #${m[1]} está en camino.${m[2] ? ' Las respuestas aparecerán en Ayuda → Mensajes.' : ''}`],
  // The undo buttons' tooltips: "Undo Move (Ctrl+Z)", "Redo (Ctrl+Y, Ctrl+Shift+Z)"
  [/^(Undo|Redo) \(([^()]+)\)$/, (m) => `${m[1] === 'Undo' ? 'Deshacer' : 'Rehacer'} (${m[2]})`],
  [/^(Undo|Redo) (.+?)(?: \(([^()]+)\))?$/, (m) => `${m[1] === 'Undo' ? 'Deshacer' : 'Rehacer'} ${ES[m[2]] ?? m[2]}${m[3] ? ` (${m[3]})` : ''}`],
  // The remarks: "3 of 4 elements found", "Imported review.bcfzip: 2 remarks (1 new, 1 updated)."
  [/^(\d+) of (\d+) elements found$/, (m) => `${m[1]} de ${m[2]} elementos encontrados`],
  [/^Imported (.+): (\d+) remarks \((\d+) new, (\d+) updated\)\.$/, (m) => `Importado ${m[1]}: ${m[2]} observaciones (${m[3]} nuevas, ${m[4]} actualizadas).`],
];
